  function setVillagePrepared(result,focus=true){villagePrepared={baseFields:result.proposal?JSON.parse(JSON.stringify(result.proposal.payload)):null,...result,revision:d().revision,session:state.session,requestId:crypto.randomUUID()};saveDraft();if(focus){render();$('village-preview')?.scrollIntoView({block:'start'});highlightResult('village-preview');}}
